/* JINI illustrated dress-up characters — HD sprite atlas with independent gear layers. */
(function () {
  "use strict";
  const SPECIES={rabbit:"토끼",cat:"고양이",bear:"곰",fox:"여우"};
  const Y={rabbit:"0%",cat:"33.333333%",bear:"66.666667%",fox:"100%"};
  const X=["0%","50%","100%"];
  const POS={hat:{ribbon:0,flower:1,crown:2,scholar:3},outfit:{academy:0,robe:1,royal:2},bag:{backpack:0,premium:1,explorer:2},book:{special:1,royal:2,cosmic:3}};
  const ROW={hat:0,outfit:1,bag:2,book:3};
  const css=`
/* High-definition evolution characters with independently swappable equipment layers. */
.jgc-mascot{display:block!important;position:relative;width:100%;height:100%;aspect-ratio:1;flex:none;isolation:isolate;overflow:visible!important}
.jgc-base-art,.jgc-mascot-layer{position:absolute;display:block;pointer-events:none; background-repeat:no-repeat;image-rendering:auto}
.jgc-base-art{inset:0;background-image:url("data:image/avif;base64,");background-size:300% 400%;background-position:var(--jgc-x) var(--jgc-y);z-index:1}
.jgc-mascot-layer{z-index:4;background-image:url("data:image/webp;base64,");background-size:400% 400%;background-position:var(--part-x) var(--part-y);filter:drop-shadow(0 2px 2px #3c264033)}
.jgc-mascot-stage-1{--hd-size:.76}
.jgc-mascot-stage-2{--hd-size:1}
.jgc-mascot-stage-3{--hd-size:1.22}
.jgc-layer-hat{width:calc(19% * var(--hd-size));height:calc(19% * var(--hd-size));left:calc(50% - 9.5% * var(--hd-size));top:calc(19% - 5% * (var(--hd-size) - .76))}
.jgc-layer-outfit{width:calc(23% * var(--hd-size));height:calc(23% * var(--hd-size));left:calc(50% - 11.5% * var(--hd-size));top:60%;z-index:3}
.jgc-layer-bag{width:calc(21% * var(--hd-size));height:calc(21% * var(--hd-size));left:calc(27% - 5% * (var(--hd-size) - .76));top:61%;z-index:5}
.jgc-layer-book{width:calc(23% * var(--hd-size));height:calc(23% * var(--hd-size));left:calc(34% - 1% * (var(--hd-size) - .76));top:52%;z-index:6}
.jgc-mascot-stage-3 .jgc-layer-hat{top:8%}
.jgc-mascot-stage-3 .jgc-layer-outfit{top:58%}
.jgc-mascot-stage-3 .jgc-layer-book{top:51%}
.jgc-mascot-stage-3 .jgc-layer-bag{top:62%}
.jgc-item-art{display:inline-block;width:42px;height:42px;flex:none;background-image:url("data:image/webp;base64,");background-size:400% 400%;background-position:var(--part-x) var(--part-y);background-repeat:no-repeat}
.jgc-item-art.jgc-item-empty{background:none;display:grid;place-items:center;border-radius:12px;background-color:#f3f1f6;font-size:17px;color:#807a90}
.jgc-sparkles{position:absolute;inset:5%;z-index:7;pointer-events:none;filter:drop-shadow(0 0 4px #fff1a9);font-size:18px;color:#f1bf73}
`;
  let style=document.getElementById("jini-ai-art-styles");
  if(!style){style=document.createElement("style");style.id="jini-ai-art-styles";document.head.appendChild(style);}
  style.textContent=css;
  function attrs(slot,id){
    if(!POS[slot]||!Object.prototype.hasOwnProperty.call(POS[slot],id))return null;
    return '--part-x:'+(["0%","33.333333%","66.666667%","100%"][POS[slot][id]])+';--part-y:'+(["0%","33.333333%","66.666667%","100%"][ROW[slot]])+';';
  }
  function itemPreview(slot,id){
    const style=attrs(slot,id);
    return style?'<span class="jgc-item-art" style="'+style+'" aria-hidden="true"></span>':'<span class="jgc-item-art jgc-item-empty" aria-hidden="true">—</span>';
  }
  function render(config){
    config=config||{};
    const animal=Object.prototype.hasOwnProperty.call(SPECIES,config.avatar)?config.avatar:"rabbit";
    const level=Math.max(1,Number(config.level)||1);
    const stage=level>=100?3:level>=50?2:1;
    const gear=config.equipped||{};
    let layers="";
    ["outfit","bag","book","hat"].forEach(function(slot){
      const style=attrs(slot,gear[slot]);
      if(style)layers+='<span class="jgc-mascot-layer jgc-layer-'+slot+'" style="'+style+'" aria-hidden="true"></span>';
    });
    return '<span class="jgc-mascot jgc-mascot-stage-'+stage+'" role="img" aria-label="'+SPECIES[animal]+' 캐릭터 성장 '+stage+'단계" style="--jgc-x:'+X[stage-1]+';--jgc-y:'+Y[animal]+'">'+
      '<span class="jgc-base-art" aria-hidden="true"></span>'+layers+'</span>';
  }
  window.JINI_CHARACTER_ART={render:render,itemPreview:itemPreview,species:Object.keys(SPECIES),style:"hd-layered-illustration"};
}());